__NUXT_JSONP__("/jp/about", (function(a,b){return {data:[{details:{slug:"jp",pageTitle:"MLIとは | Mentor Language Institute",pageDescription:b,section1:{title:"MLIとは",description:[b]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"質の高い授業をどこよりも安く",description:["アメリカには数多くの語学学校があります。数ある学校の中で当校が大切にしているもの。  それは\u003Cb\u003E「教育の質」\u003C\u002Fb\u003Eと\u003Cb\u003E「価格」\u003C\u002Fb\u003Eです。","英語はコミュニケーションのツール。1人でも多くの留学生がこのツールを身につけ、世界で 活躍してもらうこと。これが私たちの願いです。 \u003Cbr\u002F\u003Eだからこそ当校は生徒がいち早く学べる環境を整えること、そして一人でも受講しやすい価格 にこだわっています。"]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"2020年現在、17,000名以上の卒業生を輩出",description:["当校はESLをはじめ、TOEFL®、IELTS®やと言ったアメリカ大学進学に必要な試験対策コース、TOEIC＠のようなビジネスに必要な英語力を高めるプログラムを提供しています。","卒業生は英語力を高め、自国でのビジネスや、進学・就職などに活用される方はもちろん、UCLAをはじめ、USCやサンタモニカカレッジなどアメリカ大学に進学する留学生を多数輩出した実績があります。"],lists:[{link:"\u002Fjp\u002Ffeature",image:a,text:"選ばれる5つの理由へ"},{link:"\u002Fjp\u002Fcompany",image:a,text:"会社概要へ"},{link:"\u002Fjp\u002Fimage-gallery",image:a,text:"写真・動画ギャラリーへ"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:28.447Z",updatedAt:"2025-05-26T12:06:27.573Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg","当校は2002年に設立された、英語教育の専門機関です。MLIはロサンゼルスの人気エリアであるウェストウッド、ハリウッドにキャンパスを構え、世界中の留学生の英語力向上をサポートしています。")));